/// The program designs PIE builds.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Design {
    /// Grids of qwen2d / qwen2d_paged layers chained on one head (serve2d).
    Serve2d,
    /// The paged layer as a pipeline ring with the head as its stage 0 (serve2d_pipe).
    Serve2dPipe,
    /// Qwen3-8B: qwen2d_paged8b layer grids in strips, head2d v10 and the
    /// embedding strip (serve8b).
    Serve8b,
    /// Qwen3-8B as layer units: qwen2d_paged8b grids and qwen2d_region
    /// regions of several layers, chained by host tables (serve8b_region).
    Serve8bRegion,
    /// serve8b_region's units as a pipeline ring: micro-batches round the
    /// units and the head each lap (serve8b_region_pipe).
    Serve8bRegionPipe,
    /// Qwen3.5 dense: serve2d's program around Gated DeltaNet and
    /// gated-attention grids, layer by layer (serve_q35).
    ServeQ35,
    /// Gemma 4 dense: gemma4_layer grids in serve2d's chain, the f32 head2d
    /// over the tied embedding and the per-layer embedding region east of
    /// it (serve_g4).
    ServeG4,
    /// gpt-oss: per layer a gptoss_attn unit over a gptoss_moe grid in a
    /// slot, chained by host tables; head2d_v10 on chunk triples and the
    /// embedding strip (serve_gptoss).
    ServeGptoss,
}

impl Design {
    pub fn name(self) -> &'static str {
        match self {
            Design::Serve2d => "serve2d",
            Design::Serve2dPipe => "serve2d_pipe",
            Design::Serve8b => "serve8b",
            Design::Serve8bRegion => "serve8b_region",
            Design::Serve8bRegionPipe => "serve8b_region_pipe",
            Design::ServeQ35 => "serve_q35",
            Design::ServeG4 => "serve_g4",
            Design::ServeGptoss => "serve_gptoss",
        }
    }

    pub fn parse(name: &str) -> Option<Design> {
        match name {
            "serve2d" => Some(Design::Serve2d),
            "serve2d_pipe" => Some(Design::Serve2dPipe),
            "serve8b" => Some(Design::Serve8b),
            "serve8b_region" => Some(Design::Serve8bRegion),
            "serve8b_region_pipe" => Some(Design::Serve8bRegionPipe),
            "serve_q35" => Some(Design::ServeQ35),
            "serve_g4" => Some(Design::ServeG4),
            "serve_gptoss" => Some(Design::ServeGptoss),
            _ => None,
        }
    }

    /// The eta VM image the design's sources carry (enabled by its params).
    pub fn vm_image(self) -> Option<&'static str> {
        match self {
            Design::Serve2d | Design::ServeQ35 => Some("guest4hm"),
            // The guest4hz image: one or two resident sets (VMB).
            Design::Serve2dPipe => Some("guest4hz"),
            // serve_g4: head2d's stand-in VM column only.
            Design::Serve8b | Design::ServeG4 | Design::ServeGptoss => None,
            // guest4hz as the block east of the strip (with VMX).
            Design::Serve8bRegion | Design::Serve8bRegionPipe => Some("guest4hz"),
        }
    }

    /// How a KV-staging build's slots hold their elements (`kvst_pack`):
    /// f32 words on serve2d*, bf16 one a word on serve8b_region, bf16 pairs
    /// in serve8b's aliased scratch; and whether they alias it.
    pub fn kv_staging(self) -> (&'static str, bool) {
        match self {
            // serve_g4 builds no staging (KVST 0).
            Design::Serve2d | Design::Serve2dPipe | Design::ServeQ35 | Design::ServeG4 => {
                ("f32", false)
            }
            Design::Serve8b => ("bf16x2", true),
            Design::Serve8bRegion | Design::Serve8bRegionPipe | Design::ServeGptoss => {
                ("bf16", false)
            }
        }
    }

    /// [`Design::files`], or with `w4` the u4g64-weight variant (W4 1:
    /// serve8b_region and its pipe only; the default files are untouched).
    pub fn files_w4(self, w4: bool) -> R<Vec<File>> {
        self.files_for(Variant::default(), w4)
    }

    /// [`Design::files_with`] for a model `variant`, with `w4` its u4g64
    /// units ([`Design::files_w4`]).
    pub fn files_for(self, variant: Variant, w4: bool) -> R<Vec<File>> {
        match (self, w4) {
            (_, false) => self.files_with(variant),
            (Design::Serve8bRegion, true) => serve8b_region_w4(false, true, variant),
            (Design::Serve8bRegionPipe, true) => serve8b_region_w4(true, true, variant),
            (d, true) => Err(format!("{} has no u4g64 (W4) variant", d.name())),
        }
    }

    /// Every file of the program's build directory, `layout.csl` first.
    pub fn files(self) -> R<Vec<File>> {
        self.files_with(Variant::default())
    }

    /// [`Design::files`] for a model `variant`: the default's files are
    /// [`Design::files`]' byte for byte; another variant patches the layer
    /// units (serve8b_region and serve8b_region_pipe only).
    pub fn files_with(self, variant: Variant) -> R<Vec<File>> {
        if variant != Variant::default()
            && !matches!(self, Design::Serve8bRegion | Design::Serve8bRegionPipe)
        {
            return Err(format!(
                "{}: no model variant ({variant:?}); serve8b_region's units take one",
                self.name()
            ));
        }
        match self {
            Design::Serve2d => serve2d(),
            Design::Serve2dPipe => serve2d_pipe(),
            Design::Serve8b => serve8b(),
            Design::Serve8bRegion => serve8b_region(false, variant),
            Design::Serve8bRegionPipe => serve8b_region(true, variant),
            Design::ServeQ35 => serve_q35(),
            Design::ServeG4 => serve_g4(),
            Design::ServeGptoss => serve_gptoss(),
        }
    }
}

/// What a model changes in the paged8b layer units, as text patches on the
/// kernels (the default patches nothing).
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
pub struct Variant {
    /// No q/k RMSNorm (Llama): the per-head sums of squares, their segment
    /// all-reduce and the two scales are cut; the norm weights (`qkn_w`)
    /// still scale q and k (the host writes 1/sqrt(head_dim) and 1).
    pub identity_qk_norm: bool,
    /// The RMSNorm epsilon's f32 bits, when not the kernels' literal 1e-6.
    pub eps_bits: Option<u32>,
    /// `SPD` 1: the units' op cuts (`speed_ops*.json`; a faster, slightly
    /// more exact exp, otherwise the same arithmetic).
    pub speed: bool,
    /// `LSE` 1 (with `speed`): each layer's softmax runs against the last
    /// pass's log-sum-exp instead of an all-reduced max (one all-reduce fewer;
    /// a pass whose sums leave [2^-80, 2^101) is redone by every PE), and the
    /// all-reduces' group arithmetic is shifts (no soft divide/modulo).
    pub lse: bool,
    /// `OP2` 1 (with `lse`): the second op cuts (`ops2.json`): SiLU's one
    /// element a row as scalars (MC 1), set_axis skipped when the axis is
    /// already right, and PROF 1's MLP marks split (11 gate-up mv, 12 its
    /// all-reduce, 14 SiLU, 10 the act all-reduce, 13 down mv).
    pub ops2: bool,
    /// `RGX` > 0 (with `ops2`): the regions' X full all-reduces in groups
    /// of RGX (`rgx_ops.json`; the host's `rcfg` carries the third route
    /// set and log2(RGX)).
    pub rgx: bool,
    /// `QKV1` 1 (with `ops2`, B 1, W16 1): q's two RoPE halves and v as one
    /// matvec: `wqa` holds a layer's [Hc][q a | q v | v] rows (the host's
    /// `serve8b::unit` lays them out), `wqv` and `wv` are 2-word dummies.
    pub qkv1: bool,
    /// `ARF` > 0 (with `ops2`, regions only): the FIFO dual-input
    /// all-reduces (`arf_ops.json`; bit 1 the Y axis's four, bit 2 also the
    /// X axis's two full ones, `arx_ops.json`: ARF 3; bit 4 also the segment
    /// all-reduce on each row's segments of Gs columns, `arfs_ops.json`: ARF 7,
    /// the host's X set as segment streamed halves). 0: off.
    pub arf: u16,
    /// `F16` > 0: an IEEE f16 build (the program compiles without
    /// `--fp16-format=bf16`): KV stored as f16 (both units), the head's
    /// `bf16` type as `@fp16()`; 2: also the regions' weight matvecs
    /// accumulating in f16 (`f16acc_ops.json`); 3: the grids' too. 0: bf16.
    pub f16: u16,
    /// `MEM` 1 (with `arf`, regions only): the region kernel's code cuts
    /// that keep every op and cost no cycles (`mem_ops.json`): ~0.5 KB a PE
    /// (PROF 1: ~0.8 KB); bit 2 (with `identity_qk_norm`): q's 1/sqrt(128)
    /// as a constant and a one-word qkn_w the host does not write
    /// (`mem_qkn.json`, -336 B). 0: off.
    pub mem: u16,
    /// `OP3` 1 (with `ops2`, regions only): RoPE's per-lane cos/sin and
    /// their repeat once a pass (the NL layers share the position), each
    /// layer rotating every head by seven DSD ops (`op3_ops.json`). 0: off.
    pub op3: u16,
    /// `GRD` bits (grids only; 0 off): the regions' levers in the grid
    /// kernel too, as the model states them: 1 `arf` (with `ARF`), 2 `op3`
    /// (with `OP3`), 4 `mem` (with `MEM`).
    pub grid: u16,
    /// `F16CL` 1 (with `f16`): the regions' f16 probability copy clamped and
    /// the redo window narrowed (0515's form) instead of scaled; grids keep
    /// the scaled copy.
    pub f16cl: bool,
    /// `XAC` 1 (with ARF 3, regions only, KVCP 0): the XA all-reduces' (O,
    /// down) level-1 / level-2 colours their own (0, 1, 2, 15), routed once at
    /// init, so a switch to or from XA rebinds the queues and rewrites c_bc's
    /// route alone.
    pub xac: bool,
    /// `TRM` bits (B 1, MC 1, with `qkv1`, `ops2` and the unit's f16
    /// accumulation; 0 off): **1** op cuts that keep every result
    /// (`trm_ops.json`: each weight matvec's f16 accumulator zeroed directly
    /// instead of an f32 zero and its f16 copy, the gate/up rms scale applied
    /// to the one element a row's SiLU reads, the QKV rms scale as one
    /// multiply, RoPE without its copy; with MEM 3 also q's scale in one op,
    /// `trm_qscl.json`); **2** x's sums of squares by a scalar loop instead of
    /// a halving tree (`trm_ssq.json`; another summation order; the first
    /// form, a stride-0 accumulate, was wrong on hardware: 0530);
    /// **4** the grids take them too; **8** exp's polynomial at degree 4
    /// (near-minimax on |r| <= ln2/2, relative error 2.7e-6 against f16's 2.4e-4
    /// for the probabilities and SiLU's output) and SiLU's reciprocal in two
    /// Newton steps (1.2e-5; `trm_exp.json`); **16** the O and down residuals
    /// added by the all-reduce's own receive (O's redo flag moved to the
    /// front, so a redone pass adds nothing) and act received straight into
    /// the down matvec's f16 x (`trm_fuse.json`, with ARF 3); **32** the
    /// head's MODE 2 split_x as bf16(x) alone (`head_trim`); **64** HV's
    /// zeroings by reads (`trm_hv.json`: the scores' first product onto a
    /// zero run, the sums' first row copied, the reference read in place).
    pub trim: u16,
}

impl Variant {
    /// The variant's patches on a paged8b unit kernel (`tag` names it).
    fn apply(self, text: &str, tag: &str) -> R<String> {
        let mut s = text.to_string();
        let region = tag.starts_with("qwen2d_region/");
        // (GRD: a region lever on the grid kernel as well)
        let unit = |bit: u16| region || (self.grid & bit) != 0;
        if !region && self.grid & 4 != 0 && self.grid & 1 == 0 {
            // (MEM's phase1/phase2 on X only hold under ARF)
            return Err(format!("gen: {tag}: GRD 4 (MEM) needs GRD 1 (ARF)"));
        }
        if self.identity_qk_norm {
            let start = "  const sqa = @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{QH} -> s[@as(i16, QH) + i] });\n";
            let end = "  @fmuls(half_v, half_v, scl_t());\n";
            let bad = || format!("gen: {tag} changed: the q/k RMSNorm block not found once");
            if s.matches(start).count() != 1 || s.matches(end).count() != 1 {
                return Err(bad());
            }
            let a = s.find(start).ok_or_else(bad)?;
            let b = a + s[a..].find(end).ok_or_else(bad)? + end.len();
            let block = &s[a..b];
            if !block.contains("allreduce_seg(ssq3_dsd, NH * B);\n")
                || !block.contains("  axis_xx();\n")
            {
                return Err(bad());
            }
            // The axis switch stays right after the QKV all-reduce (the next
            // collective, the scores', is along X); `k` is the layer's.
            s = format!(
                "{}  // (identity q/k norm: no per-head RMSNorm)\n  axis_xx();\n  var k: u16 = 0;\n{}",
                &s[..a],
                &s[b..]
            );
        }
        if self.speed {
            s = apply_reps("speed_ops", src::SPEED_OPS, &s, tag)?;
            if tag.starts_with("qwen2d_region/") {
                s = apply_reps("speed_ops_region", src::SPEED_OPS_REGION, &s, tag)?;
            } else if self.lse {
                // (the grids under LSE: q's bf16 parts only, for HV's scores; the
                // region's scores/RoPE cuts made a grid layer slower on 0468)
                s = apply_reps("speed_ops_qparts", src::SPEED_OPS_QPARTS, &s, tag)?;
            }
        }
        if self.lse {
            if !self.speed {
                return Err(format!("gen: {tag}: LSE needs SPD (exp_fast's clamp)"));
            }
            s = apply_reps("lse_ops", src::LSE_OPS, &s, tag)?;
            // The reference's layer: a region's current one (`lw` of `NL`), a
            // grid's only one.
            let at = "var mref = @zeros([LNL * NQB]f32);\n";
            let def = if tag.starts_with("qwen2d_region/") {
                "const LNL: u16 = NL;\nfn lsel() u16 { return lw; }\nfn kvoff() u16 { return lw * KCN; }\n"
            } else {
                "const LNL: u16 = 1;\nfn lsel() u16 { return 0; }\nfn kvoff() u16 { return 0; }\n"
            };
            s = patch(
                &s,
                at,
                &format!("{def}{at}"),
                &format!("{tag}'s LSE reference"),
            )?;
            // PS 1 pages: the attention over the kv head's query heads (dead
            // code at other page sizes).
            s = apply_reps("hv_ops", src::HV_OPS, &s, tag)?;
        }
        if self.ops2 {
            if !self.lse {
                return Err(format!("gen: {tag}: OP2 needs LSE"));
            }
            s = apply_reps("ops2", src::OPS2, &s, tag)?;
        }
        if self.qkv1 {
            if !self.ops2 {
                return Err(format!("gen: {tag}: QKV1 needs OP2"));
            }
            s = qkv1(&s, tag)?;
        }
        if self.rgx && tag.starts_with("qwen2d_region/") {
            if !self.ops2 {
                return Err(format!("gen: {tag}: RGX needs OP2"));
            }
            s = apply_reps("rgx_ops", src::RGX_OPS, &s, tag)?;
        }
        if self.arf != 0 && unit(1) {
            if !self.ops2 {
                return Err(format!("gen: {tag}: ARF needs OP2"));
            }
            if self.arf != 1 && self.arf != 3 && self.arf != 7 {
                return Err(format!("gen: {tag}: ARF {} unknown (1: the Y axis, 3: and X, 7: and the X segments)", self.arf));
            }
            s = apply_reps("arf_ops", src::ARF_OPS, &s, tag)?;
            if self.arf & 2 != 0 {
                s = apply_reps("arx_ops", src::ARX_OPS, &s, tag)?;
            }
        }
        if self.f16 != 0 {
            if self.f16 > 3 {
                return Err(format!("gen: {tag}: F16 {} unknown (1 f16, 2 f16 accumulation in the regions, 3 and the grids)", self.f16));
            }
            if !self.ops2 {
                return Err(format!("gen: {tag}: F16 needs OP2"));
            }
            // KV in f16: the store rounds to the program's 16-bit float.
            s = patch(
                &s,
                "    return @as(u16, (u + 0x7fff + ((u >> 16) & 1)) >> 16);\n",
                "    return @bitcast(u16, @as(@fp16(), @bitcast(f32, u)));   // (f16)\n",
                &format!("{tag}'s F16 kv_store"),
            )?;
            // No scalar f32 -> @fp16() conversions in an IEEE build (0498-0503:
            // the layers hang there, the head and handoffs alone run): the
            // HV append converts k and v by DSD ops, the values matvec reads
            // the probabilities from an f16 copy made by one @fs2h.
            s = patch(
                &s,
                "  var d: u16 = 0;\n  while (d < Dc) : (d += 1) {\n    const kidx = (if (d < DHc) 0 else QH) + Qh * DHc + d % DHc;\n    kc[1 + kvoff() + blk * Dc + d] = kv_store(qkv[kidx]);\n    vc[1 + kvoff() + blk * Dc + d] = kv_store(qkv[QKN + d]);\n  }\n",
                "  // (f16) k's two RoPE halves and v rounded by DSD ops\n  const kb = @set_dsd_length(kat(kc_dsd, blk * Dc), DHc);\n  @fs2h(kb, @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{DHc} -> qkv[@as(i16, Qh * DHc) + i] }));\n  @fs2h(@increment_dsd_offset(kb, @as(i16, DHc), @fp16()), @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{DHc} -> qkv[@as(i16, QH + Qh * DHc) + i] }));\n  @fs2h(@set_dsd_length(kat(vc_dsd, blk * Dc), Dc), @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{Dc} -> qkv[@as(i16, QKN) + i] }));\n",
                &format!("{tag}'s F16 HV append"),
            )?;
            s = patch(
                &s,
                "  @fmovs(o_all, 0.0);\n",
                "  @fmovs(o_all, 0.0);\n  // (f16) the probabilities as f16, for the values matvec's scalars (NS <= XMAX)\n  @fs2h(@set_dsd_length(xpart_dsd, NS), @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{NS} -> s[i] }));\n",
                &format!("{tag}'s F16 probabilities"),
            )?;
            s = patch(
                &s,
                "@fmachs(od, od, vb, @as(@fp16(), s[e * NQB + b * Qh + h]));",
                "@fmachs(od, od, vb, xpart[e * NQB + b * Qh + h]);   // (f16)",
                &format!("{tag}'s F16 values"),
            )?;
            // No inf / NaN from the f16 range (0507: a layer that reached its
            // residual hung the chip, one cut before it ran; a pass still on a
            // stale reference has probabilities up to e^75, whose f16 copy was
            // inf, and o NaN from there on). The copy is scaled by 2^-k, k from
            // this PE's largest head sum (its slots' p sum, before the all-reduce)
            // so every copied p is < 2^15 and that sum's copy is a normal f16; the
            // values' partials are scaled back by 2^k (exact) before the
            // all-reduce. The redo window stays bf16's [2^-80, 2^101) (0509 /
            // 0515's narrower [2^-8, 2^15) redid passes: Qwen ~0.5 a pass in some
            // regions). PROF 0 counts the redos by side in prof[2] / prof[3].
            // (F16CL: the regions as 0515 - the copy min(p, 65504) made as
            // -max(-p, -65504) in place, the values carrying -p and divided by
            // -l, and a pass redone when its sum leaves [2^-8, 2^15): no scale's
            // cost; Llama's regions redid <= 0.011 a pass there, its last grid
            // 0.26 + 0.16, Qwen's regions up to 0.4: the grids keep the scale)
            if region && self.f16cl {
                s = patch(
                    &s,
                    "  @fs2h(@set_dsd_length(xpart_dsd, NS), @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{NS} -> s[i] }));\n",
                    "  @fnegs(s_scores, s_scores);\n  @fmaxs(s_scores, s_scores, -65504.0);   // (f16) -min(p, f16 max)\n  @fs2h(@set_dsd_length(xpart_dsd, NS), @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{NS} -> s[i] }));\n",
                    &format!("{tag}'s F16 clamp"),
                )?;
                for (old, new) in [
                    ("    bcv[j] = recip(l);\n", "    bcv[j] = -recip(l);   // (f16) the values carry -p\n"),
                    (
                        "    if (e < 770048.0 or e >= 3735552.0) { bad = 1.0; }\n",
                        "    // (f16) the sum in [2^-8, 2^15); PROF 0 counts the redos by side in prof[2] / prof[3]\n    if (e < 1949696.0) { bad = 1.0; if (PROF == 0) { prof[2] += 1; } }\n    if (e >= 2326528.0) { bad = 1.0; if (PROF == 0) { prof[3] += 1; } }\n",
                    ),
                ] {
                    s = patch(&s, old, new, &format!("{tag}'s F16 range"))?;
                }
            } else {
                s = patch(
                    &s,
                    "  @fs2h(@set_dsd_length(xpart_dsd, NS), @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{NS} -> s[i] }));\n",
                    concat!(
                        "  // (f16) a scaled copy: 2^-k with this PE's largest head sum in [2^14, 2^15)\n",
                        "  var lm: f32 = 0.0;\n",
                        "  var jm: u16 = 0;\n",
                        "  while (jm < dims[3]) : (jm += 1) { if (gu[B * QO + jm] > lm) { lm = gu[B * QO + jm]; } }\n",
                        "  const eb: u32 = (@bitcast(u32, lm) >> 23) & 0xff;\n",
                        "  var sc: f32 = 1.0;\n",
                        "  f16_inv = 1.0;\n",
                        "  if (eb >= 15) {\n",
                        "    sc = @bitcast(f32, (268 - eb) << 23);\n",
                        "    f16_inv = @bitcast(f32, (eb - 14) << 23);\n",
                        "  }\n",
                        "  // (only the scored slots: the rest hold -1e30, which the scale could overflow)\n",
                        "  const nsc: u16 = if (HV) hv_n * NQB else NS;\n",
                        "  if (nsc > 0) {\n",
                        "    @fmuls(@set_dsd_length(s_scores, nsc), @set_dsd_length(s_scores, nsc), sc);\n",
                        "    @fs2h(@set_dsd_length(xpart_dsd, nsc), @set_dsd_length(s_scores, nsc));\n",
                        "  }\n",
                    ),
                    &format!("{tag}'s F16 scaled copy"),
                )?;
                s = patch(
                    &s,
                    "  mark(6);\n",
                    "  @fmuls(o_all, o_all, f16_inv);   // (f16) the partials back to p's scale\n  mark(6);\n",
                    &format!("{tag}'s F16 rescale"),
                )?;
                s = patch(
                    &s,
                    "var mref = @zeros([LNL * NQB]f32);\n",
                    "var mref = @zeros([LNL * NQB]f32);\nvar f16_inv: f32 = 1.0;   // (f16) 2^k of the probabilities' copy\n",
                    &format!("{tag}'s F16 scale"),
                )?;
                s = patch(
                    &s,
                    "    if (e < 770048.0 or e >= 3735552.0) { bad = 1.0; }\n",
                    concat!(
                        "    if (e < 770048.0) { bad = 1.0; if (PROF == 0) { prof[2] += 1; } }   // (f16) redos by side\n",
                        "    if (e >= 3735552.0) { bad = 1.0; if (PROF == 0) { prof[3] += 1; } }\n",
                    ),
                    &format!("{tag}'s F16 redo count"),
                )?;
            }
            // (F16 3: the grids' matvecs too; the same anchors in their kernel)
            if (self.f16 == 2 && tag.starts_with("qwen2d_region/")) || self.f16 == 3 {
                s = apply_reps("f16acc_ops", src::F16ACC_OPS, &s, tag)?;
            }
        }
        if self.mem != 0 && unit(4) {
            if self.mem != 1 && self.mem != 3 {
                return Err(format!("gen: {tag}: MEM {} unknown (1: the code cuts, 3: and q's constant scale)", self.mem));
            }
            if self.mem & 2 != 0 && !self.identity_qk_norm {
                return Err(format!("gen: {tag}: MEM 3 needs the identity q/k norm"));
            }
            if self.arf == 0 {
                return Err(format!("gen: {tag}: MEM needs ARF"));
            }
            s = apply_reps("mem_ops", src::MEM_OPS, &s, tag)?;
            if self.mem & 2 != 0 {
                if region {
                    s = apply_reps("mem_qkn", src::MEM_QKN, &s, tag)?;
                } else {
                    // (GRD: the grid's one layer - qkn_w unstacked, no `lw`)
                    let j = src::MEM_QKN
                        .replace("[NL * 2 * NH * DHc]", "[2 * NH * DHc]")
                        .replace("at(qkn_a, lw * 2 * NH * DHc)", "qkn_a")
                        .replace("at(qkn_v, lw * 2 * NH * DHc)", "qkn_v");
                    s = apply_reps("mem_qkn (grid)", &j, &s, tag)?;
                }
            }
        }
        if self.op3 != 0 && unit(2) {
            if self.op3 != 1 {
                return Err(format!("gen: {tag}: OP3 {} unknown (1: RoPE a pass)", self.op3));
            }
            if !self.ops2 {
                return Err(format!("gen: {tag}: OP3 needs OP2"));
            }
            if !region {
                // (GRD: the grids lack the regions' RV rotation; speed_ops_region's
                // two RoPE entries, 3 and 4, bring it in first)
                let all: serde_json::Value = serde_json::from_str(src::SPEED_OPS_REGION)
                    .map_err(|e| format!("speed_ops_region.json: {e}"))?;
                let two = serde_json::Value::Array(
                    all.as_array().ok_or("speed_ops_region.json: not a list")?[3..5].to_vec(),
                );
                s = apply_reps("speed_ops_region RoPE (grid)", &two.to_string(), &s, tag)?;
            }
            s = apply_reps("op3_ops", src::OP3_OPS, &s, tag)?;
        }
        if self.xac && region {
            if self.arf & 3 != 3 {
                return Err(format!("gen: {tag}: XAC needs ARF 3"));
            }
            s = xac(&s, tag)?;
        }
        if self.arf & 4 != 0 && unit(1) {
            // (ARF 7: the segment all-reduce on the host's segment streamed halves;
            // the anchors are ARF 3's and, in the regions, XAC's)
            if region && !self.xac {
                return Err(format!("gen: {tag}: ARF 7 needs XAC in the regions"));
            }
            s = apply_reps("arfs_ops", src::ARFS_OPS, &s, tag)?;
        }
        if self.trim != 0 && (region || self.trim & 4 != 0) {
            if self.trim & 1 == 0 || self.trim > 127 {
                return Err(format!("gen: {tag}: TRM {} unknown (1 the cuts, 2 and the sums of squares, 4 the grids too, 8 exp at degree 4, 16 the residuals from the fabric, 32 the head's split_x, 64 HV's zero copies)", self.trim));
            }
            if self.trim & 16 != 0 && self.arf & 3 != 3 {
                return Err(format!("gen: {tag}: TRM 16 needs ARF 3"));
            }
            if !(self.qkv1 && self.ops2 && self.f16 >= if region { 2 } else { 3 }) {
                return Err(format!("gen: {tag}: TRM needs QKV1, OP2 and the unit's f16 accumulation"));
            }
            s = apply_reps("trm_ops", src::TRM_OPS, &s, tag)?;
            if self.trim & 2 != 0 {
                s = apply_reps("trm_ssq", src::TRM_SSQ, &s, tag)?;
            }
            if self.identity_qk_norm && self.mem & 2 != 0 && unit(4) {
                s = apply_reps("trm_qscl", src::TRM_QSCL, &s, tag)?;
            }
            if self.trim & 8 != 0 {
                s = apply_reps("trm_exp", src::TRM_EXP, &s, tag)?;
            }
            if self.trim & 16 != 0 {
                s = apply_reps("trm_fuse", src::TRM_FUSE, &s, tag)?;
            }
            if self.trim & 64 != 0 {
                s = apply_reps("trm_hv", src::TRM_HV, &s, tag)?;
            }
        }
        if let Some(bits) = self.eps_bits {
            let eps = f32::from_bits(bits);
            if !(eps.is_finite() && eps > 0.0) {
                return Err(format!("gen: RMSNorm eps {eps} is not a positive number"));
            }
            let mut lit = format!("{eps:e}");
            if !lit.contains('.') {
                lit = lit.replacen('e', ".0e", 1);
            }
            s = patch(
                &s,
                "const EPS: f32 = 1.0e-6;\n",
                &format!("const EPS: f32 = {lit};\n"),
                &format!("{tag}'s EPS"),
            )?;
        }
        Ok(s)
    }
}

// ---------------------------------------------------------------- gpt-oss

/// gpt-oss's MoE grid unit: qwen2d_paged8b_hr's infrastructure (memcpy,
/// collectives, init/compute, x and its table) with layer() = moe_mlp(),
/// the dense MLP's tiles cut to a word, and moe_mxfp4 appended. This is the
/// source the simulator (t1, t2) and CS-3 (0446) ran, less their debug
/// exports (`payload/moe_mxfp4/gen.py`).
pub fn gptoss_moe() -> R<String> {
    let hr = src::QWEN2D_PAGED8B_HR;
    let s = patch(
        hr,
        "var wgu: [Hc * 2 * Ic + 1]WS align(16) = @zeros([Hc * 2 * Ic + 1]WS);",
        "var wgu: [2]WS align(16) = @zeros([2]WS);",
        "moe: wgu",
    )?;
    let s = patch(
        &s,
        "var wd: [Ic * Hc + 1]WS align(16) = @zeros([Ic * Hc + 1]WS);",
        "var wd: [2]WS align(16) = @zeros([2]WS);",
        "moe: wd",
    )?;
    let (Some(a), Some(b)) = (s.find("fn layer() void {"), s.find("fn rebase16() void {")) else {
        return Err("gen: moe: layer()/rebase16() anchors".into());
    };
    Ok(format!(
        "{}fn layer() void {{ moe_mlp(); }}\n\n{}{}",
        &s[..a],
        &s[b..],
        src::MOE_MXFP4
    ))
}

/// `XAC`'s patches on the region kernel (after ARF 3's): XA's level-1 and
/// level-2 colours are its own (0, 1, 2, 15: no handoff routes them through a
/// region PE, test `xac_colours_are_free_on_regions`), routed once at init, and
/// arf_qv binds XA's queues to them; c_bc stays shared, so a switch to or from
/// XA rewrites its route alone; the other shared colours' routes are rewritten
/// only between Y and X seg.
fn xac(text: &str, tag: &str) -> R<String> {
    let what = |w: &str| format!("{tag}'s XAC {w}");
    let mut s = patch(
        text,
        "const a_oq6 = tile_config.output_queue_config.get_output_queue_config_addr(6);\n",
        "const a_oq6 = tile_config.output_queue_config.get_output_queue_config_addr(6);\n\
         // (xac) XA's c_r1_0, c_r1_1, c_r2_0, c_r2_1 on their own colours, routed once (arf_setup).\n\
         comptime { @comptime_assert(KVCP == 0 and HROUTE == 1); }\n\
         const XAC_C = [4]u16 { 0, 1, 2, 15 };\n\
         const xaddr = [4]u16 { @as(u16, color_config.get_color_config_addr(@get_color(0))),\n\
         \x20 @as(u16, color_config.get_color_config_addr(@get_color(1))), @as(u16, color_config.get_color_config_addr(@get_color(2))),\n\
         \x20 @as(u16, color_config.get_color_config_addr(@get_color(15))) };\n\
         var rt_cur: u16 = 3;   // (xac) the shared colours' routes: 0 Y, 1 X seg, 3 none yet\n",
        &what("colours"),
    )?;
    s = patch(
        &s,
        "fn arf_setup() void {\n  arf_qv(0, rcfg[2 * NCOL + 1]);\n  arf_qv(12, rcfg[3 * NCOL + 2]);   // (arx)\n}\n",
        "fn arf_setup() void {\n  arf_qv(0, rcfg[2 * NCOL + 1]);\n  arf_qv(12, rcfg[3 * NCOL + 2]);   // (arx)\n\
         \x20 var i: u16 = 0;   // (xac) XA's own colours' routes, once\n\
         \x20 while (i < 4) : (i += 1) { put_route(xaddr[i], rcfg[2 * NCOL + 2 + i]); }\n}\n",
        &what("setup"),
    )?;
    for (i, (k, c)) in [("c10", "c_r1_0"), ("c11", "c_r1_1"), ("c20", "c_r2_0"), ("c21", "c_r2_1")].into_iter().enumerate() {
        s = patch(
            &s,
            &format!("  const {k}: u16 = @get_int({c});\n"),
            &format!("  const {k}: u16 = if (o == 12) XAC_C[{i}] else @get_int({c});   // (xac)\n"),
            &what(k),
        )?;
    }
    s = patch(
        &s,
        "  hy_qv[6] = b_i3 | c10; hy_qv[7] = b_o4 | (c11 << 4); hy_qv[8] = b_i5 | c20;\n  hy_qv[9] = b_o6 | (c21 << 4); hy_qv[10] = b_i6 | c21; hy_qv[11] = b_i4 | c11;\n",
        "  if (o == 0) {   // (xac) X seg's defaults: the shared colours\n\
         \x20 hy_qv[6] = b_i3 | c10; hy_qv[7] = b_o4 | (c11 << 4); hy_qv[8] = b_i5 | c20;\n\
         \x20 hy_qv[9] = b_o6 | (c21 << 4); hy_qv[10] = b_i6 | c21; hy_qv[11] = b_i4 | c11;\n  }\n",
        &what("X seg defaults"),
    )?;
    s = patch(
        &s,
        "  if (axis_cur == want) { return; }\n  axis_cur = want;\n",
        "  if (axis_cur == want) { return; }\n  const was_xa = axis_cur == 2;   // (xac)\n  axis_cur = want;\n",
        &what("previous axis"),
    )?;
    s = patch(
        &s,
        "    var i: u16 = 0;\n    while (i < NCOL) : (i += 1) { put_route(caddr[i], rcfg[ar_off[want] + i]); }\n    return;\n",
        "    // (xac) XA: c_bc's route alone; Y / X seg: all five when the set changes,\n\
         \x20   // else c_bc's back from XA\n\
         \x20   if (want != 2 and rt_cur != want) {\n\
         \x20     rt_cur = want;\n\
         \x20     var i: u16 = 0;\n\
         \x20     while (i < NCOL) : (i += 1) { put_route(caddr[i], rcfg[ar_off[want] + i]); }\n\
         \x20   } else if (want == 2 or was_xa) {\n\
         \x20     put_route(caddr[4], rcfg[ar_off[want] + 4]);\n\
         \x20   }\n    return;\n",
        &what("switch"),
    )?;
    Ok(s)
}

/// `QKV1`'s patch on a paged8b unit kernel (grid or region): one QKV
/// matvec over fused rows (Hc ops of length QKW instead of 3 x Hc).
fn qkv1(text: &str, tag: &str) -> R<String> {
    let region = tag.starts_with("qwen2d_region/");
    let nl = if region { "NL * " } else { "" };
    let what = |w: &str| format!("{tag}'s QKV1 {w}");
    let mut s = patch(
        text,
        &format!(
            "var wqa: [{nl}Hc * NH * DHc + 1]WS align(16) = @zeros([{nl}Hc * NH * DHc + 1]WS);\n"
        ),
        &format!(
            "// (qkv1) a layer's [Hc][q a | q v | v] rows: one matvec of QKW a row.\n\
             const QKW: u16 = 2 * NH * DHc + Dc;\n\
             comptime {{ @comptime_assert(B == 1 and W16 == 1); }}\n\
             var wqa: [{nl}Hc * QKW + 1]WS align(16) = @zeros([{nl}Hc * QKW + 1]WS);\n"
        ),
        &what("wqa"),
    )?;
    s = patch(
        &s,
        "var wqa_dsd = if (W16 == 1) @get_dsd(mem1d_dsd, .{ .base_address = &wdummy, .extent = NH * DHc })\n              else @get_dsd(mem1d_dsd, .{ .tensor_access = |i|{NH * DHc} -> wqa[i + 1] });\n",
        "var wqa_dsd = @get_dsd(mem1d_dsd, .{ .base_address = &wdummy, .extent = QKW });\n",
        &what("wqa_dsd"),
    )?;
    s = patch(
        &s,
        &format!(
            "var wqv: [{nl}Hc * NH * DHc + 1]WS align(16) = @zeros([{nl}Hc * NH * DHc + 1]WS);\n"
        ),
        "var wqv: [2]WS align(16) = @zeros([2]WS);   // (qkv1) in wqa\n",
        &what("wqv"),
    )?;
    s = patch(
        &s,
        &format!("var wv: [{nl}Hc * Dc + 1]WS align(16) = @zeros([{nl}Hc * Dc + 1]WS);\n"),
        "var wv: [2]WS align(16) = @zeros([2]WS);   // (qkv1) in wqa\n",
        &what("wv"),
    )?;
    s = patch(
        &s,
        "    wmv(at(qh_dsd, b * NH * DHc), wqa_dsd, xb, Hc, sc_s);\n    wmv(at(qh_dsd, QH + b * NH * DHc), wqv_dsd, xb, Hc, sc_s);\n    wmv(at(v_dsd, b * Dc), wv_dsd, xb, Hc, sc_s);\n",
        "    // (qkv1) B 1: q a, q v (at QH) and v (at QKN = 2 QH) are contiguous.\n    wmv(@get_dsd(mem1d_dsd, .{ .tensor_access = |i|{QKW} -> qkv[i] }), wqa_dsd, xb, Hc, sc_s);\n",
        &what("matvec"),
    )?;
    let (a, q, v) = if region {
        (
            "&wqa[1 + l * Hc * NH * DHc]",
            "&wqv[1 + l * Hc * NH * DHc]",
            "&wv[1 + l * Hc * Dc]",
        )
    } else {
        ("&wqa[1]", "&wqv[1]", "&wv[1]")
    };
    let a2 = if region {
        "&wqa[1 + l * Hc * QKW]"
    } else {
        "&wqa[1]"
    };
    s = patch(
        &s,
        &format!(
            "    wqa_dsd = @set_dsd_base_addr(wqa_dsd, @ptrcast([*]@fp16(), {a}));\n    wqv_dsd = @set_dsd_base_addr(wqv_dsd, @ptrcast([*]@fp16(), {q}));\n    wv_dsd = @set_dsd_base_addr(wv_dsd, @ptrcast([*]@fp16(), {v}));\n"
        ),
        &format!("    wqa_dsd = @set_dsd_base_addr(wqa_dsd, @ptrcast([*]@fp16(), {a2}));\n"),
        &what("bases"),
    )?;
    Ok(s)
}

// ---------------------------------------------------------------- text helpers

/// `old` replaced by `new`; `old` must occur exactly once.
fn patch(text: &str, old: &str, new: &str, what: &str) -> R<String> {
    let n = text.matches(old).count();
    if n != 1 {
        return Err(format!("gen: anchor for '{what}' found {n} times"));
    }
    Ok(text.replacen(old, new, 1))
}

/// The names a source exports (`@export_symbol(ptr, "name")`).
fn exports(text: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut rest = text;
    while let Some(i) = rest.find("@export_symbol(") {
        rest = &rest[i + "@export_symbol(".len()..];
        let ident_len = rest
            .bytes()
            .take_while(|b| b.is_ascii_alphanumeric() || *b == b'_')
            .count();
        if ident_len == 0 {
            continue;
        }
        let after = &rest[ident_len..];
        if let Some(q) = after.strip_prefix(", \"") {
            let name_len = q
                .bytes()
                .take_while(|b| b.is_ascii_alphanumeric() || *b == b'_')
                .count();
            if name_len > 0 && q[name_len..].starts_with("\")") {
                out.push(q[..name_len].to_string());
            }
        }
    }
    out
}

/// An insertion-ordered name -> type map (Python dict semantics: updating a
/// key keeps its place).
#[derive(Clone, Default)]
struct Names(Vec<(&'static str, &'static str)>);

impl Names {
    fn of(items: &[(&'static str, &'static str)]) -> Names {
        let mut n = Names::default();
        n.update(items);
        n
    }

    fn update(&mut self, items: &[(&'static str, &'static str)]) {
        for &(k, v) in items {
            match self.0.iter_mut().find(|(kk, _)| *kk == k) {
                Some(e) => e.1 = v,
                None => self.0.push((k, v)),
            }
        }
    }

    fn with(&self, items: &[(&'static str, &'static str)]) -> Names {
        let mut n = self.clone();
        n.update(items);
        n
    }
}

/// The start of the block `\n(//[^\n]*\n)*<head>`: the newline before the
/// comment lines directly above `head` (or before `head` itself).
fn comment_block_start(s: &str, head_at: usize) -> Option<usize> {
    if head_at == 0 || s.as_bytes()[head_at - 1] != b'\n' {
        return None;
    }
    let mut start = head_at - 1;
    loop {
        // The line ending at `start` (exclusive).
        let line_start = s[..start].rfind('\n').map(|i| i + 1)?;
        if s[line_start..start].starts_with("//") {
            start = line_start - 1;
        } else {
            return Some(start);
        }
    }
}

/// The range of `\n(//[^\n]*\n)*<head>.*?\n}\n`, for the first `head` (at a
/// line start) that has one.
fn fn_block(s: &str, head: &str) -> Option<(usize, usize)> {
    let mut from = 0;
    while let Some(i) = s[from..].find(head) {
        let at = from + i;
        if let Some(start) = comment_block_start(s, at) {
            let end = at + s[at..].find("\n}\n")? + 3;
            return Some((start, end));
        }
        from = at + 1;
    }
    None
}

/// `re.sub(r"\n(\s*)<call>", r"\n\1<call>\n\1<extra>", s)` and the match count.
fn after_each_call(s: &str, call: &str, extra: &str) -> (String, usize) {
    let mut out = String::with_capacity(s.len() + 256);
    let mut last = 0;
    let mut n = 0;
    let mut from = 0;
    while let Some(i) = s[from..].find(call) {
        let at = from + i;
        // The maximal whitespace run before `call`; the match starts at its first newline.
        let ws_start = s[..at]
            .char_indices()
            .rev()
            .take_while(|(_, c)| c.is_whitespace())
            .last()
            .map(|(j, _)| j)
            .unwrap_or(at);
        match s[ws_start..at].find('\n') {
            Some(k) if ws_start >= last => {
                let nl = ws_start + k;
                let group = &s[nl + 1..at];
                out.push_str(&s[last..nl]);
                out.push('\n');
                out.push_str(group);
                out.push_str(call);
                out.push('\n');
                out.push_str(group);
                out.push_str(extra);
                last = at + call.len();
                n += 1;
            }
            _ => {}
        }
        from = at + call.len();
    }
    out.push_str(&s[last..]);
    (out, n)
}

/// The names a layout exports (`@export_name("n", ...)`), in order.
#[cfg(test)]
pub(crate) fn layout_exports(layout: &str) -> Vec<String> {
    layout
        .split("@export_name(")
        .skip(1)
        .filter_map(|rest| {
            rest.trim_start()
                .strip_prefix('"')?
                .split_once('"')
                .map(|(n, _)| n.to_string())
        })
        .collect()
}

