// ---------------------------------------------------------------- serve8b

/// The fast softmax levers (S1: the max-shift and rescale as one 2-D op, exp
/// over act-sized chunks; S2: the max and sum folds as a halving tree; S3:
/// the exp sums ride the values all-reduce) on an 8B unit kernel's text,
/// each anchor found once.
fn softmax_s123(text: &str, tag: &str) -> R<String> {
    apply_reps("softmax_s123", src::SOFTMAX_S123, text, tag)
}

/// The softmax levers S1 and S3 on the 0.6B paged layer
/// (qwen2d_paged / qwen2d_pring; S2 is already there).
fn softmax_s13_06b(text: &str, tag: &str) -> R<String> {
    apply_reps("softmax_s13_06b", src::SOFTMAX_S13_06B, text, tag)
}

/// A JSON list of {old, new} text pairs applied in order, each anchor found once.
/// `F16`: the head's `bf16` type (legal only with `--fp16-format=bf16`) as
/// `@fp16()`, IEEE f16 in an F16 build; comments untouched.
/// `TRM` bit 32 on the head: MODE 2's split_x makes bf16(x) alone (one pass,
/// no certify: the other two parts and |x - bf16(x)|^2 are never read).
fn head_trim(text: &str) -> R<String> {
    patch(
        text,
        "fn split_x() void {\n  const p0 = xp_dsd;\n",
        "fn split_x() void {\n  const p0 = xp_dsd;\n  // (trm 32) one pass, no certify: bf16(x) alone (the other parts and rs are unread)\n  if (ONEPASS and !CERTIFY) { @fs2h(p0, xs_dsd); return; }\n",
        "the head's split_x (TRM 32)",
    )
}

fn f16_head(text: &str) -> String {
    let mut out = String::with_capacity(text.len() + 256);
    for line in text.split_inclusive('\n') {
        let (code, rest) = line.find("//").map_or((line, ""), |i| line.split_at(i));
        let mut c = String::with_capacity(code.len());
        let b = code.as_bytes();
        let mut i = 0;
        while i < code.len() {
            let word = |j: usize| j < b.len() && (b[j].is_ascii_alphanumeric() || b[j] == b'_');
            if code[i..].starts_with("bf16") && (i == 0 || !word(i - 1)) && !word(i + 4) {
                c.push_str("@fp16()");
                i += 4;
            } else {
                let ch = code[i..].chars().next().unwrap_or(' ');
                c.push(ch);
                i += ch.len_utf8();
            }
        }
        out.push_str(&c);
        out.push_str(rest);
    }
    out
}

fn apply_reps(name: &str, json: &str, text: &str, tag: &str) -> R<String> {
    let reps: serde_json::Value =
        serde_json::from_str(json).map_err(|e| format!("{name}.json: {e}"))?;
    let mut s = text.to_string();
    for (i, r) in reps.as_array().ok_or(format!("{name}.json: not a list"))?.iter().enumerate() {
        let (old, new) = (
            r["old"].as_str().unwrap_or(""),
            r["new"].as_str().unwrap_or(""),
        );
        let n = s.matches(old).count();
        if old.is_empty() || n != 1 {
            return Err(format!("{name}: {tag} changed: anchor {i} found {n} times"));
        }
        s = s.replacen(old, new, 1);
    }
    Ok(s)
}

